import * as Api from '@/api/workflow/selectUser';


import * as _ from 'lodash';

export default {
    name: 'SelectUser',
    components: {},
    props: {
        value: {
            type: Array,
            default: () => {
                return [];
            }
        }, // 选中的值
        isRadio: {type: Boolean, default: false}, // 单选
        title: {type: String, default: '参与者'} // 默认选择参与者
    },
    data() {
        return {
            searchKey: '',
            users: [], // 用户列表
            depts: [], // 部门组织机构
            selected: [], // 选中的值
            showUser: [], // 单行文本显示的选项
            showDialog: false, // 弹框的状态 true - 打开； false - 关闭
            defaultProps: {
                label: 'label',
                children: 'childrenList',
                isLeaf: 'isLeaf'
            }, // tree的配置项
            indent: 10, // 树结构的层级
            searchPopoverShow: false, // 搜索popover
            isSearchInputBG: false, // 搜索框背景改变
            searchResult: [], // 搜索结果
            // filterText: '', // 过滤树的关键字
            tableItem: {}, // 表格搜索条件
            tableLoading: false, // 表格加载状态
            multipleSelection: [], // 表格多选状态
            currentPage: 1, // 默认每页显示的条数（可修改）
            PageSize: 10, // 选项
            totalCount: 0, // 总条数
            radioTypeSelectedUser: {}, // 单选的时候选择的用户
            isExpand: true, // 是否懒加载
            lazyTreeKey: new Date() + 'tree' // 懒加载树的key值
        };
    },
    watch: {
        searchKey: {
            handler(n) {
                // const this = this;
                if (n === '') {
                    this.isExpand = false;
                    this.search();
                }
            },
            deep: true
        },
        // 用户名称和部门列表
        users: {
            handler(n) {
                if (n.length) {
                    // const this = this;
                    this.$nextTick(() => {
                        this.$refs.multipleTable.clearSelection();
                        this.selected.forEach(item => {
                            n.findIndex(it => {
                                const index = it.id === item.id;
                                if (index) {
                                    this.$refs.multipleTable.toggleRowSelection(it, true);
                                }
                            });
                        });
                    });
                }
            },
            deep: true
        },
        // 监听被选中表格数据
        multipleSelection: {
            handler(n) {
                // const this = this;
                n.forEach(item => {
                    const index = this.selected.findIndex(it => it.id === item.id);
                    if (index < 0) {
                        this.selected.push(item);
                    }
                });
            },
            deep: true
        },
        // 弹框的显示与隐藏
        showDialog: {
            handler(n) {
                // const this = this;
                if (n) {
                    this.selected = _.cloneDeep(this.value) || [];
                    if (this.value.length && this.isRadio)
                        this.radioTypeSelectedUser = _.cloneDeep(this.value[0]);
                    this.showUser = _.cloneDeep(this.selected);
                } else {
                    this.cancel();
                }
            },
            deep: true
        },
        // 选中的用户 props传递过来的值
        value: {
            handler(n) {
                // const this = this;
                this.selected = _.cloneDeep(n) || [];
                if (n.length && this.isRadio)
                    this.radioTypeSelectedUser = _.cloneDeep(n[0]);
                this.showUser = _.cloneDeep(n) || [];
            },
            deep: true,
        },
        // 选择的用户 单选的时候
        radioTypeSelectedUser: {
            handler(n) {
                // const this = this;
                if (this.isRadio) {
                    this.selected = Object.keys(n).length ? [n] : [];
                }
            },
            deep: true
        }
    },
    mounted() {
        // const this = this;
        this.selected = this.value || [];
        this.showUser = _.cloneDeep(this.selected);
    },
    methods: {
        cloneDeep(obj) {
            if (typeof obj !== 'object' || obj == null) {
                return obj;
            }
            let res;
            if (obj instanceof Array) {
                res = [];
            } else {
                res = {};
            }
            for (let key in obj) {
                if (obj.hasOwnProperty.call(key)) {
                    res[key] = _.cloneDeep(obj[key]);
                }
            }
            return res;
        },
        // 点击搜索打开弹框
        clickShowDialog() {
            // const this = this;
            this.showDialog = true;
            this.lazyTreeKey = `${new Date()}tree`; // 改变el-tree的key值会触发load事件
            this.isExpand = false;
        },
        // 初始化部门组织结构
        initDepts(node, resolve) {
            // const this = this;
            const params = {
                id: node && node.data && node.data.id ? node.data.id : '-1'
            };
            Api.getDepts(params)
                .then(res => {
                    if (res && res.code && res.code === 10000) {
                        if (params.id === '11') {
                            this.deptNodeClick({type: 'organ', id: ''});
                        }
                        resolve(res.data || []);
                        this.isExpand = false;
                    } else {
                        this.$message({
                            message: '',
                            type: 'error'
                        });
                    }
                })
                .catch(() => {
                    this.$message({
                        message: '获取部门组织机构异常',
                        type: 'error'
                    });
                });
        },
        // 点击部门组织节点, 获取部门下用户
        deptNodeClick(data) {
            // const this = this;
            this.tableItem = data;
            const params = {
                id: data.id,
                type: data.type,
                size: this.PageSize,
                current: this.currentPage,
                label: this.searchKey
            };
            this.tableLoading = true;
            Api.getUsers(params)
                .then(res => {
                    if (res && res.code && res.code === 10000) {
                        this.users = res.data.records || [];
                        this.totalCount = res.data.total || 0;
                        this.tableLoading = false;
                    } else {
                        this.$message({
                            message: '获取部门下用户失败',
                            type: 'error'
                        });
                    }
                })
                .catch(() => {
                    this.$message({
                        message: '获取部门下用户异常',
                        type: 'error'
                    });
                });
        },
        // 删除所有的用户
        deleteAll() {
            // const this = this;
            this.$refs.multipleTable.clearSelection();
            this.selected = [];
            this.radioTypeSelectedUser = {};
        },
        // 点击项后的删除按钮，删除某一项
        deleteItem(item, index) {
            // const this = this;
            this.multipleSelection.findIndex(it => {
                const findIndex = it.id === item.id;
                if (findIndex) {
                    this.$refs.multipleTable.toggleRowSelection(it, false);
                }
            });
            this.selected.splice(index, 1);
            this.radioTypeSelectedUser = {};
        },
        // 点击搜索用户
        search() {
            // const this = this;
            this.searchResult = [];
            this.searchPopoverShow = false;
            if (this.searchKey && this.searchKey !== '') {
                const params = {
                    organName: this.searchKey
                };
                Api.searchUsers(params)
                    .then(res => {
                        if (res && res.code && res.code === 10000) {
                            const user = [];
                            const organ = [];
                            res.data.forEach(item => {
                                if (item.type === 'user') {
                                    user.push(item);
                                } else {
                                    organ.push(item);
                                }
                            });
                            this.searchResult.push({
                                label: `用户（${hussar-user.length}）`,
                                options: user,
                                show: false
                            });
                            this.searchResult.push({
                                label: `部门（${organ.length}）`,
                                options: organ,
                                show: false
                            });
                        } else {
                            this.$message({
                                message: '关键字查询用户列表失败',
                                type: 'error'
                            });
                        }
                        this.searchPopoverShow = true;
                    })
                    .catch(() => {
                        this.$message({
                            message: '关键字查询用户列表异常',
                            type: 'error'
                        });
                    });
            } else {
                this.deptNodeClick({type: 'organ', id: ''});
            }
        },
        // 点击确定，保存当前选中的的用户
        confirm() {
            // const this = this;
            if (this.isRadio && this.selected.length !== 1) {
                this.$message({
                    message: `请选择${this.title}`,
                    type: 'warning'
                });
                this.showDialog = true;
                return;
            }
            if (this.selected.length > 20) {
                this.$message({
                    message: `选择的${this.title}数量不能超过20`,
                    type: 'warning'
                });
                this.showDialog = true;
                return;
            }
            if (this.selected.length === 0) {
                this.$message({
                    message: `至少选择一名${this.title}`,
                    type: 'warning'
                });
                this.showDialog = true;
                return;
            }
            this.$emit('update:value', this.selected);
            this.showUser = _.cloneDeep(this.selected);
            this.cancel();
        },
        // 点击取消，不保存当前选中的用户
        cancel() {
            // const this = this;
            this.showDialog = false;
            this.depts = [];
            this.searchResult = [];
            this.searchKey = '';
            // this.filterText = '';
            this.tableItem = {};
            this.currentPage = 1;
            this.users = [];
            this.isExpand = true;
        },
        // 点击×关闭弹框
        handleClose() {
            // const this = this;
            this.cancel();
        },
        // 组织机构树的渲染
        renderContent(h, {node}) {
            let iconType = '';
            if (node.level === 1) {
                iconType = 'tree-com';
            } else if (node.level === 2) {
                iconType = 'tree-department';
            } else {
                iconType = 'unit';
            }
            return (  <div class="tree-div">
            <span class="staff-tree">
            <span className="svg-icon">
            <svg-icon icon-class={iconType}/>
          </span>
          {node.label}
        </span>
          </div>
        );
        },
        // 获取焦点
        inpFocus() {
            this.isSearchInputBG = true;
            if (this.searchResult.length) {
                this.searchPopoverShow = true;
            }
        },
        // 失去焦点
        inpBlur() {
            // const this = this;
            this.isSearchInputBG = false;
            this.searchPopoverShow = false;
        },
        // 搜索
        changeFilter() {
            // const this = this;
            this.search();
        },
        // 点击查询到的列表数据
        changeInput(data) {
            // const this = this;
            this.searchKey = data.label;
            if (data.type === 'organ') {
                // 部门 -- 搜索部门 查询部门下的用户
                this.deptNodeClick(data);
            } else {
                // 用户 -- 搜索用户
                this.deptNodeClick(data);
            }
            this.searchOrganTree(data);
            this.searchPopoverShow = false;
        },
        // table多选
        handleSelectionChange(val) {
            // const this = this;
            this.multipleSelection = val;
        },
        // 表格多选切换
        handleSelect(selection, row) {
            // 相当于取消选中
            // const this = this;
            if (selection.indexOf(row) < 0) {
                const index = this.selected.findIndex(it => it.id === row.id);
                this.selected.splice(index, 1);
            }
        },
        // table点击全选复选框
        selectAll(val) {
            // const this = this;
            if (val.length === 0) {
                this.selected = [];
            }
        },
        // 显示第几页
        handleCurrentChange(val) {
            // 改变默认的页数
            // const this = this;
            this.currentPage = val;
            this.deptNodeClick(this.tableItem);
        },
        // 点击当前行，选中当前行
        clickUsersRow(row) {
            // const this = this;
            this.radioTypeSelectedUser = {id: row.id, label: row.label};
            this.$refs.multipleTable.toggleRowSelection(row);
            this.handleSelect(this.multipleSelection, row);
        },
        // 选择用户或者部门的时候
        searchOrganTree(data) {
            // const this = this;
            Api.searchOrganTree(data)
                .then(res => {
                    if (res && res.code && res.code === 10000) {
                        this.isExpand = true;
                        this.depts = res.data || [];
                    } else {
                        this.$message({
                            message: '搜索组织机构失败',
                            type: 'error'
                        });
                    }
                })
                .catch(() => {
                    this.$message({
                        message: '搜索组织机构异常',
                        type: 'error'
                    });
                });
        },
        // 删除选择的用户，在文本框中
        deleteUser() {
            // const this = this;
            this.showUser.splice(0, 1);
            this.$emit('input', this.showUser);
        },
        // 部门名称为空时，显示-
        showEmptyDeptName(row, column, cellValue) {
            return cellValue && cellValue !== '' ? cellValue : '-';
        }
    }
};
